async checkLocalPassword(username, password) {
  const identity = await this.identityService.getIdentityFromUserIdAndProviderType(username, AuthProviderType.LOCAL, null);
  const passwordValid = await checkPassword(password, identity.password_hash ?? '');
  if (!passwordValid) throw new InvalidCredentialsError('Username or password is not correct');
  return identity;
}

@UseGuards(GuestsEnabledGuard)
@Post('login')
async loginGuestUser(@Req() request, @Body() loginDto: GuestLoginDto) {
  const userId = await this.usersService.getUserIdByGuestUuid(loginDto.uuid);
  request.session.loginAuthProviderType = AuthProviderType.GUEST;
  request.session.userId = userId;
}

@UseGuards(RegistrationEnabledGuard)
@Post()
async registerUser(@Req() request, @Body() registerDto: RegisterDto) {
  await this.localIdentityService.checkPasswordStrength(registerDto.password);
  const userId = await this.localIdentityService.createUserWithLocalIdentity(registerDto.username, registerDto.password, registerDto.displayName);
  request.session.loginAuthProviderType = AuthProviderType.LOCAL;
  request.session.userId = userId;
  request.session.pendingUser = null;
}

@UseGuards(SessionGuard)
@Delete('logout')
async logout(@Req() request) {
  if (request.session.loginAuthProviderType === AuthProviderType.OIDC) logoutUrl = this.oidcService.getLogoutUrl(request);
  const destroy = promisify(request.session.destroy.bind(request.session));
  await destroy();
  return LogoutResponseDto.create({ redirect: logoutUrl || '/' });
}

