async setUserPermission(noteId, userId, canEdit) {
  return this.knex.transaction(async t => {
    if (await this.isOwner(userId, noteId, t)) return;
    if (!await this.userService.isRegisteredUser(userId, t)) throw new PermissionError('Note permissions can not be granted to guests');
    await t(TableNoteUserPermission).insert({ userId, noteId, canEdit }).onConflict(['note_id','user_id']).merge();
    this.notifyOthers(noteId);
  });
}

async removeUserPermission(noteId, userId) {
  const result = await this.knex(TableNoteUserPermission).where('note_id', noteId).andWhere('user_id', userId).delete();
  await this.knex(TableVisitedNote).where('note_id', noteId).andWhere('user_id', userId).delete();
  if (result !== 1) throw new NotInDBError('The user does not have a permission on this note.');
  this.notifyOthers(noteId);
}

async setGroupPermission(noteId, groupId, canEdit) {
